-- ============================================================
-- Spawns. Group ids 1520006101+; coordinates via anchored SELECTs
-- where exact guide coords are unknown; seeds marked TUNABLE.
-- ============================================================
DELETE FROM `spawnentry` WHERE `spawngroupID` BETWEEN 1520006101 AND 1520006120;
DELETE FROM `spawn2` WHERE `spawngroupID` BETWEEN 1520006101 AND 1520006120;
DELETE FROM `spawngroup` WHERE `id` BETWEEN 1520006101 AND 1520006120;

-- King Ak`Anon inside the static Mansion, east wing (TUNABLE seed,
-- anchored to the static-zone Meldrath district).
SELECT 1520006101,'mansion',0,300,260,52,250,640;

-- Technician Masterwork: top of Gyrospire Zeka (highest existing z).
SELECT 1520006102,'gyrospirez',0,x+15,y-15,z,0,1500 FROM `spawn2` WHERE `zone`='gyrospirez' ORDER BY `z` DESC LIMIT 1;

-- Engineer Gyrzim: Gyrospire Beza, high walk (2nd highest existing z).
SELECT 1520006103,'gyrospireb',0,x-15,y+15,z,0,1500 FROM `spawn2` WHERE `zone`='gyrospireb' ORDER BY `z` DESC LIMIT 1 OFFSET 1;

-- Big Bynn lair (dragonscaleb instance version 52): Tinmizer controller
-- + Big Bynn, anchored near the Deepscar den floor.

-- Oxidilus the Junk Collector: PH/named cycle at the guide location
-- (2355, 922); z snapped to the nearest live steamfactory spawn.
SELECT 1520006106,'steamfactory',0,2355,922,z,0,1200 FROM `spawn2` WHERE `zone`='steamfactory' ORDER BY ABS(x-2355)+ABS(y-922) LIMIT 1;

-- Steam Raid bosses (steamfactory instance version 51). Coordinates
-- TUNABLE: anchored to three live spawns spread across the zone.
SELECT 1520006107,'steamfactory',51,x,y,z,0,86400 FROM `spawn2` WHERE `zone`='steamfactory' ORDER BY y ASC LIMIT 1;
SELECT 1520006108,'steamfactory',51,x,y,z,0,86400 FROM `spawn2` WHERE `zone`='steamfactory' ORDER BY x ASC LIMIT 1;
SELECT 1520006109,'steamfactory',51,x,y,z,0,86400 FROM `spawn2` WHERE `zone`='steamfactory' ORDER BY y DESC LIMIT 1;
